"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type TranslatePrimitiveProps = ComponentProps<typeof motion.div>;

export function TranslatePrimitive({ children, ...props }: TranslatePrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {x: 36,rotate: 12}}
      animate={{x: 0,rotate: 0}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.28, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
